document.addEventListener("DOMContentLoaded", () => {
  const container = document.querySelector(".course-container");
  const skillContainers = document.getElementsByClassName("skill-items");
  const programmingContainer = skillContainers[0];
  const frontendContainer = skillContainers[1];
  const backendContainer = skillContainers[2];
  const aiContainer = skillContainers[3];
  const databaseContainer = skillContainers[4];
  const toolsContainer = skillContainers[5];
  const projectContainer = document.querySelector(".projects-container");
  const experienceContainer = document.querySelector(".timeline");
  const testimonialsTrack = document.querySelector(".testimonials-track");
  const testimonialsDots = document.querySelector(".testimonials-dots");

  courses.forEach((course) => {
    const courseCard = `<div class="course-card">
          <div class="course-header">
            <div class="course-title">
              <i class="${course.logo}"></i>
              <h3>${course.title}</h3>
            </div>
            <div class="course-content">
              <div class="provider">
                <i class="ri-building-4-line"></i>
                <p>${course.provider}</p>
              </div>
              <a
                href="${course.link}"
                target="_blank"
                class="certificate-link">
                <i class="ri-external-link-line"></i> View Certificate
              </a>
            </div>
          </div>
          <p class="date">${course.date}</p>
        </div>`;

    container.innerHTML += courseCard;
  });

  const renderSkill = (skill, container) => {
    if (!container) return;
    const isSvg =
      skill.logo.trim().startsWith("<svg") ||
      skill.logo.trim().startsWith("<SVG");
    const iconElement =
      skill.logo === ""
        ? ""
        : isSvg
          ? skill.logo
          : `<i class="${skill.logo}" style="color: ${skill.color || ""}"></i>`;
    const isCentered = skill.name === "Linux VPS (Ubuntu)";
    const centerStyle = isCentered ? ' style="text-align: center;"' : "";

    const skillCard = `<div class="skill-item"${centerStyle}>
          ${iconElement}
          <span>${skill.name}</span>
        </div>`;
    container.innerHTML += skillCard;
  };

  programmingLanguages.forEach((skill) =>
    renderSkill(skill, programmingContainer),
  );
  frontendMobileSkills.forEach((skill) =>
    renderSkill(skill, frontendContainer),
  );
  backendApiSkills.forEach((skill) => renderSkill(skill, backendContainer));
  aiMachineLearningSkills.forEach((skill) => renderSkill(skill, aiContainer));
  databaseCloudSkills.forEach((skill) => renderSkill(skill, databaseContainer));
  toolsMethodologies.forEach((skill) => renderSkill(skill, toolsContainer));

  function getVideoPlatform(url) {
    if (!url || url === "#") return null;
    if (/youtu(\.be|be\.com)/i.test(url)) return "youtube";
    if (/drive\.google\.com/i.test(url)) return "drive";
    return null;
  }

  projects.forEach((project, idx) => {
    const hasLiveDemo = project.links.live !== "#";
    const hasVideo = project.video !== "#";
    const hasVideoLink = project.links.video && project.links.video !== "#";

    const fullDescription = project.description.trim();
    const firstSentenceMatch = fullDescription.match(/^[\s\S]+?[.!?](?=\s|$)/);
    const cardPreview = firstSentenceMatch
      ? firstSentenceMatch[0]
      : fullDescription;
    const hasBullets =
      Array.isArray(project.bullets) && project.bullets.length > 0;
    const continuesInModal =
      cardPreview.length < fullDescription.length || hasBullets;

    const coverImage = getProjectCoverImage(project);
    const galleryCount = Array.isArray(project.image)
      ? project.image.length
      : 0;
    const useAutoplaySlideshow =
      project.autoplay && Array.isArray(project.image) && galleryCount > 1;
    const deferCardMedia = idx >= 4;

    let imageHTML = "";
    let galleryHintHTML = "";

    if (useAutoplaySlideshow) {
      imageHTML = `<div class="project-slideshow" data-project-idx="${idx}">
        ${project.image
          .map((img, imgIdx) =>
            buildProjectCardImgTag(img, project.title, {
              defer: imgIdx === 0 ? deferCardMedia : true,
              className: imgIdx === 0 ? "active" : "",
            }),
          )
          .join("")}
      </div>`;

      const showDots = galleryCount <= 8;
      galleryHintHTML = `<div class="project-gallery-hint" aria-hidden="true">
          <span class="project-gallery-badge">
            <i class="ri-images-line"></i> ${galleryCount} photos
          </span>
          ${
            showDots
              ? `<div class="project-slideshow-dots">
            ${project.image
              .map(
                (_, dotIdx) =>
                  `<span class="project-slideshow-dot${dotIdx === 0 ? " active" : ""}"></span>`,
              )
              .join("")}
          </div>`
              : ""
          }
        </div>`;
    } else {
      imageHTML = buildProjectCardImgTag(coverImage, project.title, {
        defer: deferCardMedia,
      });
      galleryHintHTML =
        galleryCount > 1
          ? `<div class="project-gallery-hint" aria-hidden="true">
          <span class="project-gallery-badge">
            <i class="ri-images-line"></i> ${galleryCount} photos
          </span>
        </div>`
          : "";
    }

    const projectCard = `
    <div class="project-card" data-project-index="${idx}">
    <div class="project-image project-image-trigger" role="button" tabindex="0" aria-label="View ${project.title} screenshots">
      ${imageHTML}
      ${galleryHintHTML}
    </div>
    <div class="project-content">
      <h3>${project.title} ${project.badge ? `<span class="project-badge">${project.badge}</span>` : ""}</h3>
      <p>${cardPreview}${
        continuesInModal
          ? ` <button class="read-more-btn" data-type="project" data-index="${idx}">Read More</button>`
          : ""
      }</p>
      <div class="project-tech">
      ${project.technologies.map((tech) => `<span>${tech}</span>`).join("")}
      </div>
      <div class="project-links">
      <a href="${project.links.code}" class="btn btn-secondary" target="_blank" data-analytics="code" data-project="${project.title}">
        <i class="ri-github-line"></i> Code
      </a>
      ${
        hasLiveDemo
          ? `<a href="${project.links.live}" class="btn" target="_blank" data-analytics="live_demo" data-project="${project.title}">
          <i class="ri-external-link-line"></i> Live Demo
          </a>`
          : ""
      }
      ${
        hasVideo
          ? `<a class="btn btn-video-preview" data-project-idx="${idx}"><i class="ri-play-circle-line"></i> Video Preview</a>`
          : ""
      }
      ${
        hasVideoLink
          ? `<a href="${project.links.video}" class="btn" target="_blank" data-analytics="external_video" data-project="${project.title}" data-platform="${getVideoPlatform(project.links.video) || ""}"><i class="ri-play-circle-line"></i> Video</a>`
          : ""
      }
      </div>
    </div>
    </div>`;

    projectContainer.innerHTML += projectCard;
  });

  // Show only first 4 projects initially
  const projectCards = document.querySelectorAll(".project-card");
  projectCards.forEach((card, idx) => {
    if (idx >= 4) {
      card.style.display = "none";
      card.classList.add("hidden-project");
    }
  });

  // Add Show More button
  if (projectCards.length > 4) {
    const showMoreBtn = document.createElement("div");
    showMoreBtn.style.textAlign = "center";
    showMoreBtn.style.marginTop = "2rem";
    showMoreBtn.innerHTML = `<button class="btn show-more-projects-btn" style="font-size: 1rem; padding: 0.75rem 2rem;">Show More Projects</button>`;
    projectContainer.parentNode.insertBefore(
      showMoreBtn,
      projectContainer.nextSibling,
    );

    document
      .querySelector(".show-more-projects-btn")
      .addEventListener("click", function () {
        projectCards.forEach((card) => {
          card.style.display = "";
          card.classList.remove("hidden-project");
          promoteLazyImages(card);
        });
        this.parentElement.style.display = "none";
      });
  }

  function renderExperienceBullets(bullets) {
    return `<ul class="award-description">${bullets
      .map((item) => `<li>${item}</li>`)
      .join("")}</ul>`;
  }

  function getExperienceSnippet(bullets) {
    const firstBullet = bullets[0] || "";
    const hasMore = bullets.length > 1 || firstBullet.length > 70;
    const shortDescription =
      firstBullet.length > 70
        ? `${firstBullet.substring(0, 70)}...`
        : firstBullet;
    return { shortDescription, hasMore };
  }

  function renderExperienceReadMoreButton(expIdx, roleIdx = null) {
    const roleAttr = roleIdx === null ? "" : ` data-role-index="${roleIdx}"`;
    return `<button class="read-more-btn" data-type="experience" data-index="${expIdx}"${roleAttr}>Read More</button>`;
  }

  function renderExperienceCertificate(link, company) {
    if (link === "#") return "";
    return `
            <a href="${link}" class="btn" target="_blank" data-analytics="view_certificate" data-company="${company}">
              <i class="fa-solid fa-certificate"></i> View Certificate
            </a>`;
  }

  experience.forEach((exp, idx) => {
    const headerIcon = exp.icon
      ? exp.icon
      : `<img src="${exp.logo}" alt="${exp.company}" loading="lazy" decoding="async"> `;

    if (Array.isArray(exp.roles) && exp.roles.length) {
      const rolesHTML = exp.roles
        .map((role, roleIdx) => {
          const { shortDescription, hasMore } = getExperienceSnippet(
            role.bullets,
          );
          const showReadMore = hasMore || role.bullets.length > 0;
          return `
        <div class="timeline-role">
          <h4>${role.title}</h4>
          <p class="date">${role.date}</p>
          <p class="description">${shortDescription}${
            showReadMore
              ? ` ${renderExperienceReadMoreButton(idx, roleIdx)}`
              : ""
          }</p>
          ${renderExperienceCertificate(role.link, exp.company)}
        </div>`;
        })
        .join("");

      experienceContainer.innerHTML += `
    <div class="timeline-item">
      <div class="timeline-dot"></div>
      <div class="timeline-content">
        <div class="timeline-header">
          ${headerIcon}
          <h3>${exp.company}</h3>
        </div>
        <div class="timeline-roles">${rolesHTML}</div>
      </div>
    </div>`;
      return;
    }

    const { shortDescription, hasMore } = getExperienceSnippet(exp.bullets);

    experienceContainer.innerHTML += `
    <div class="timeline-item">
      <div class="timeline-dot"></div>
      <div class="timeline-content">
        <div class="timeline-header">
        ${headerIcon}
          <h3>${exp.company}</h3>
        </div>
        <h4>${exp.title}</h4>
        <p class="date">${exp.date}</p>
        <p class="description">${shortDescription}${
          hasMore ? ` ${renderExperienceReadMoreButton(idx)}` : ""
        }</p>
        ${renderExperienceCertificate(exp.link, exp.company)}
      </div>
    </div>`;
  });

  // Modal for video preview
  const videoModal = document.createElement("div");
  videoModal.className = "video-modal";
  videoModal.innerHTML = `
    <div class="video-modal-overlay"></div>
    <div class="video-modal-content" role="dialog" aria-modal="true" aria-label="Project video preview">
      <button type="button" class="video-modal-close" aria-label="Close video">&times;</button>
      <h3 class="video-modal-title"></h3>
      <div class="video-modal-body"></div>
    </div>`;
  document.body.appendChild(videoModal);

  function openVideoModal(idx) {
    const project = projects[idx];
    const modalBody = videoModal.querySelector(".video-modal-body");
    videoModal.querySelector(".video-modal-title").textContent = project.title;

    if (project.video && project.video !== "#") {
      modalBody.innerHTML = `<video class="video-modal-player" controls autoplay preload="none" playsinline></video>`;
      const player = modalBody.querySelector(".video-modal-player");
      player.src = project.video;
      player.load();
    } else {
      modalBody.innerHTML = `<div class="video-placeholder">Video preview coming soon...</div>`;
    }
    videoModal.classList.add("open");
    document.body.style.overflow = "hidden";

    if (typeof window.trackAnalytics === "function") {
      window.trackAnalytics("click", "video_preview", {
        project: project.title,
        source: "modal",
      });
    }
  }

  function closeVideoModal() {
    const player = videoModal.querySelector(".video-modal-player");
    if (player) {
      player.pause();
      player.removeAttribute("src");
      player.load();
    }
    videoModal.classList.remove("open");
    videoModal.querySelector(".video-modal-body").innerHTML = "";
    if (!document.querySelector(".photo-slideshow-modal.open")) {
      document.body.style.overflow = "";
    }
  }

  document.querySelectorAll(".btn-video-preview").forEach((btn) => {
    btn.addEventListener("click", function (e) {
      const idx = this.getAttribute("data-project-idx");
      openVideoModal(idx);
    });
  });

  videoModal
    .querySelector(".video-modal-close")
    .addEventListener("click", closeVideoModal);
  videoModal
    .querySelector(".video-modal-overlay")
    .addEventListener("click", closeVideoModal);

  // Modal for project photo slideshow
  const photoSlideshowModal = document.createElement("div");
  photoSlideshowModal.className = "photo-slideshow-modal";
  photoSlideshowModal.innerHTML = `
    <div class="photo-slideshow-modal-overlay"></div>
    <div class="photo-slideshow-modal-content" role="dialog" aria-modal="true" aria-label="Project screenshots">
      <button type="button" class="photo-slideshow-modal-close" aria-label="Close slideshow">&times;</button>
      <h3 class="photo-slideshow-modal-title"></h3>
      <div class="photo-slideshow-modal-body">
        <button type="button" class="photo-slideshow-nav photo-slideshow-prev" aria-label="Previous image">
          <i class="ri-arrow-left-s-line"></i>
        </button>
        <img class="photo-slideshow-modal-image" src="" alt="" />
        <button type="button" class="photo-slideshow-nav photo-slideshow-next" aria-label="Next image">
          <i class="ri-arrow-right-s-line"></i>
        </button>
      </div>
      <div class="photo-slideshow-counter"></div>
    </div>`;
  document.body.appendChild(photoSlideshowModal);

  let photoSlideshowImages = [];
  let photoSlideshowIndex = 0;

  function getProjectImages(project) {
    return Array.isArray(project.image) ? project.image : [project.image];
  }

  function getActiveCardSlideIndex(imageArea) {
    const slideshow = imageArea.querySelector(".project-slideshow");
    if (!slideshow) return 0;
    const images = slideshow.querySelectorAll("img");
    for (let i = 0; i < images.length; i++) {
      if (images[i].classList.contains("active")) return i;
    }
    return 0;
  }

  function updatePhotoSlideshowView() {
    const imageEl = photoSlideshowModal.querySelector(
      ".photo-slideshow-modal-image",
    );
    const counterEl = photoSlideshowModal.querySelector(
      ".photo-slideshow-counter",
    );
    const prevBtn = photoSlideshowModal.querySelector(".photo-slideshow-prev");
    const nextBtn = photoSlideshowModal.querySelector(".photo-slideshow-next");
    const total = photoSlideshowImages.length;
    const current = photoSlideshowImages[photoSlideshowIndex];

    imageEl.src = current;
    imageEl.alt = `${photoSlideshowModal.querySelector(".photo-slideshow-modal-title").textContent} screenshot ${photoSlideshowIndex + 1}`;
    counterEl.textContent = `${photoSlideshowIndex + 1} / ${total}`;

    const showNav = total > 1;
    prevBtn.style.display = showNav ? "" : "none";
    nextBtn.style.display = showNav ? "" : "none";
    counterEl.style.display = showNav ? "" : "none";
  }

  function openPhotoSlideshow(projectIdx, startIdx = 0) {
    const project = projects[projectIdx];
    if (!project) return;

    photoSlideshowImages = getProjectImages(project);
    photoSlideshowIndex = Math.min(
      Math.max(startIdx, 0),
      photoSlideshowImages.length - 1,
    );

    photoSlideshowModal.querySelector(
      ".photo-slideshow-modal-title",
    ).textContent = project.title;
    updatePhotoSlideshowView();
    photoSlideshowModal.classList.add("open");
    document.body.style.overflow = "hidden";
  }

  function closePhotoSlideshow() {
    photoSlideshowModal.classList.remove("open");
    photoSlideshowModal.querySelector(".photo-slideshow-modal-image").src = "";
    photoSlideshowImages = [];
    photoSlideshowIndex = 0;
    if (!videoModal.classList.contains("open")) {
      document.body.style.overflow = "";
    }
  }

  function showPreviousPhoto() {
    if (photoSlideshowImages.length <= 1) return;
    photoSlideshowIndex =
      (photoSlideshowIndex - 1 + photoSlideshowImages.length) %
      photoSlideshowImages.length;
    updatePhotoSlideshowView();
  }

  function showNextPhoto() {
    if (photoSlideshowImages.length <= 1) return;
    photoSlideshowIndex =
      (photoSlideshowIndex + 1) % photoSlideshowImages.length;
    updatePhotoSlideshowView();
  }

  function openProjectPhotoSlideshow(imageArea) {
    const card = imageArea.closest(".project-card");
    if (!card) return;

    const projectIdx = parseInt(card.getAttribute("data-project-index"), 10);
    openPhotoSlideshow(projectIdx, getActiveCardSlideIndex(imageArea));
  }

  document.addEventListener("click", function (e) {
    const imageArea = e.target.closest(".project-image-trigger");
    if (!imageArea) return;
    openProjectPhotoSlideshow(imageArea);
  });

  document.addEventListener("keydown", function (e) {
    const imageArea = e.target.closest(".project-image-trigger");
    if (!imageArea) return;
    if (e.key !== "Enter" && e.key !== " ") return;
    e.preventDefault();
    openProjectPhotoSlideshow(imageArea);
  });

  photoSlideshowModal
    .querySelector(".photo-slideshow-modal-close")
    .addEventListener("click", closePhotoSlideshow);
  photoSlideshowModal
    .querySelector(".photo-slideshow-modal-overlay")
    .addEventListener("click", closePhotoSlideshow);
  photoSlideshowModal
    .querySelector(".photo-slideshow-prev")
    .addEventListener("click", showPreviousPhoto);
  photoSlideshowModal
    .querySelector(".photo-slideshow-next")
    .addEventListener("click", showNextPhoto);

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") {
      if (photoSlideshowModal.classList.contains("open")) closePhotoSlideshow();
      else if (videoModal.classList.contains("open")) closeVideoModal();
      return;
    }

    if (!photoSlideshowModal.classList.contains("open")) return;
    if (e.key === "ArrowLeft") showPreviousPhoto();
    if (e.key === "ArrowRight") showNextPhoto();
  });

  // Modal for read more content
  const readMoreModal = document.createElement("div");
  readMoreModal.className = "read-more-modal";
  readMoreModal.innerHTML = `
    <div class="read-more-modal-overlay"></div>
    <div class="read-more-modal-content">
      <button class="read-more-modal-close">&times;</button>
      <div class="read-more-modal-body"></div>
    </div>`;
  document.body.appendChild(readMoreModal);

  function openReadMoreModal(type, index, roleIndex = null) {
    const modalBody = readMoreModal.querySelector(".read-more-modal-body");

    if (type === "project") {
      const project = projects[index];
      const hasLiveDemo = project.links.live !== "#";
      const hasVideo = project.video !== "#";
      const hasVideoLink = project.links.video && project.links.video !== "#";

      const headerImage = getProjectCoverImage(project);

      modalBody.innerHTML = `
        <div class="read-more-project">
          <div class="read-more-header">
            <img src="${headerImage}" alt="${project.title}" />
            <div class="read-more-title">
              <h2>${project.title} ${project.badge ? `<span class="project-badge">${project.badge}</span>` : ""}</h2>
              <div class="read-more-tech">
                ${project.technologies
                  .map((tech) => `<span>${tech}</span>`)
                  .join("")}
              </div>
            </div>
          </div>
          <div class="read-more-description-wrapper" style="position: relative;">
            ${
              project.summary ||
              (Array.isArray(project.bullets) && project.bullets.length > 0)
                ? `<div style="display: flex; justify-content: flex-end; margin-bottom: 0.8rem;">
              <button class="btn btn-secondary btn-summarize" data-state="full" style="font-size: 0.85rem; padding: 0.4rem 1rem; height: auto;">
                <i class="fa-solid fa-compress"></i> Summarize
              </button>
            </div>`
                : ""
            }
            <div class="read-more-description">
              <p class="description-text" style="line-height: 1.6; font-size: 0.95rem;">${project.description}</p>
              ${
                Array.isArray(project.bullets) && project.bullets.length
                  ? `<ul class="read-more-bullets">${project.bullets
                      .map((bullet) => `<li>${bullet}</li>`)
                      .join("")}</ul>`
                  : ""
              }
            </div>
          </div>
          <div class="read-more-links">
            <a href="${
              project.links.code
            }" class="btn btn-secondary" target="_blank" data-analytics="code" data-project="${project.title}">
              <i class="ri-github-line"></i> View Code
            </a>
            ${
              hasLiveDemo
                ? `<a href="${project.links.live}" class="btn" target="_blank" data-analytics="live_demo" data-project="${project.title}">
              <i class="ri-external-link-line"></i> Live Demo
            </a>`
                : ""
            }
            ${
              hasVideo
                ? `<a class="btn btn-video-preview-modal" data-project-idx="${index}">
              <i class="ri-play-circle-line"></i> Video Preview
            </a>`
                : ""
            }
            ${
              hasVideoLink
                ? `<a href="${project.links.video}" class="btn" target="_blank" data-analytics="external_video" data-project="${project.title}" data-platform="${getVideoPlatform(project.links.video) || ""}">
              <i class="ri-play-circle-line"></i> Video
            </a>`
                : ""
            }
          </div>
        </div>
      `;

      // Summarize Toggle Handler
      const summarizeBtn = modalBody.querySelector(".btn-summarize");
      const descText = modalBody.querySelector(".description-text");
      const bulletsEl = modalBody.querySelector(".read-more-bullets");
      if (summarizeBtn && descText) {
        summarizeBtn.addEventListener("click", () => {
          const state = summarizeBtn.getAttribute("data-state");
          if (state === "full") {
            if (project.summary) {
              descText.innerHTML = project.summary;
            }
            if (bulletsEl) bulletsEl.style.display = "none";
            summarizeBtn.innerHTML = `<i class="fa-solid fa-expand"></i> Show Full Details`;
            summarizeBtn.setAttribute("data-state", "summary");
          } else {
            descText.innerHTML = project.description;
            if (bulletsEl) bulletsEl.style.display = "";
            summarizeBtn.innerHTML = `<i class="fa-solid fa-compress"></i> Summarize`;
            summarizeBtn.setAttribute("data-state", "full");
          }
        });
      }
    } else if (type === "experience") {
      const exp = experience[index];
      const role =
        Array.isArray(exp.roles) && roleIndex !== null
          ? exp.roles[roleIndex]
          : null;
      const title = role ? role.title : exp.title;
      const date = role ? role.date : exp.date;
      const bullets = role ? role.bullets : exp.bullets;
      const link = role ? role.link : exp.link;
      const hasCertificate = link !== "#";

      modalBody.innerHTML = `
        <div class="read-more-experience">
          <div class="read-more-header">
            ${
              exp.icon
                ? exp.icon
                : `<img src="${exp.logo}" alt="${exp.company}" loading="lazy" decoding="async">`
            }
            <div class="read-more-title">
              <h2>${exp.company}</h2>
              <h3>${title}</h3>
              <p class="date">${date}</p>
            </div>
          </div>
          <div class="read-more-description">
            ${renderExperienceBullets(bullets)}
          </div>
          ${
            hasCertificate
              ? `
          <div class="read-more-links">
            <a href="${link}" class="btn" target="_blank" data-analytics="view_certificate" data-company="${exp.company}">
              <i class="fa-solid fa-certificate"></i> View Certificate
            </a>
          </div>
          `
              : ""
          }
        </div>
      `;
    }

    readMoreModal.classList.add("open");

    if (typeof window.trackAnalytics === "function") {
      if (type === "project") {
        window.trackAnalytics("click", "read_more", {
          project: projects[index].title,
          source: "card",
        });
      } else if (type === "experience") {
        const exp = experience[index];
        const role =
          Array.isArray(exp.roles) && roleIndex !== null
            ? exp.roles[roleIndex]
            : null;
        window.trackAnalytics("click", "read_more", {
          company: exp.company,
          role: role ? role.title : exp.title,
          source: "experience",
        });
      }
    }
  }

  function closeReadMoreModal() {
    readMoreModal.classList.remove("open");
    readMoreModal.querySelector(".read-more-modal-body").innerHTML = "";
  }

  // Event listeners for read more buttons
  document.addEventListener("click", function (e) {
    const readMoreBtn = e.target.closest(".read-more-btn");
    if (readMoreBtn) {
      const type = readMoreBtn.getAttribute("data-type");
      const index = readMoreBtn.getAttribute("data-index");
      const roleIndexAttr = readMoreBtn.getAttribute("data-role-index");
      const roleIndex =
        roleIndexAttr === null ? null : parseInt(roleIndexAttr, 10);
      openReadMoreModal(type, parseInt(index, 10), roleIndex);
    }
  });

  // Event listeners for video preview in modal
  document.addEventListener("click", function (e) {
    const videoBtn = e.target.closest(".btn-video-preview-modal");
    if (videoBtn) {
      const idx = videoBtn.getAttribute("data-project-idx");
      closeReadMoreModal();
      setTimeout(() => openVideoModal(idx), 300);
    }
  });

  readMoreModal
    .querySelector(".read-more-modal-close")
    .addEventListener("click", closeReadMoreModal);
  readMoreModal
    .querySelector(".read-more-modal-overlay")
    .addEventListener("click", closeReadMoreModal);

  // Testimonials Slider Variables
  let currentTestimonialIndex = 0;
  const totalTestimonials = testimonials.length;

  // Create testimonials cards
  testimonials.forEach((testimonial, index) => {
    const avatarElement =
      testimonial.avatar === "#"
        ? `<div class="testimonial-avatar-svg">
           <i class="ri-user-line"></i>
         </div>`
        : `<img src="${testimonial.avatar}" alt="${testimonial.name}" class="testimonial-avatar" loading="lazy" decoding="async"
           onerror="this.src='https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&h=150&fit=crop&crop=face'">`;

    const positionElement =
      testimonial.position === "#" ? "" : `<p>${testimonial.position}</p>`;

    const hasLink = testimonial.link && testimonial.link !== "#";
    const linkButton = hasLink
      ? `<a href="${testimonial.link}" target="_blank" class="testimonial-link-btn" style="background-color: #3b82f6; color: white; padding: 0.5rem 1rem; border-radius: 0.5rem; display: inline-flex; align-items: center; gap: 0.5rem; text-decoration: none; margin-top: 1rem; transition: background-color 0.3s;">
          <i class="ri-feedback-line"></i> View Review
        </a>`
      : "";

    const testimonialCard = `
      <div class="testimonial-card" data-index="${index}">
        ${avatarElement}
        <div class="testimonial-content">
          <div class="testimonial-rating">
            ${Array(testimonial.rating)
              .fill('<i class="ri-star-fill"></i>')
              .join("")}
          </div>
          <p class="testimonial-text">${testimonial.text}</p>
          <div class="testimonial-author">
            <h4>${testimonial.name}</h4>
            ${positionElement}
          </div>
          ${linkButton}
        </div>
      </div>
    `;
    testimonialsTrack.innerHTML += testimonialCard;

    // Create dots
    const dot = document.createElement("div");
    dot.className = `testimonial-dot ${index === 0 ? "active" : ""}`;
    dot.addEventListener("click", () => goToTestimonial(index));
    testimonialsDots.appendChild(dot);
  });

  // Testimonials Slider Functions
  function goToTestimonial(index) {
    if (index < 0 || index >= totalTestimonials) return;

    currentTestimonialIndex = index;
    updateTestimonialsSlider();
  }

  function nextTestimonial() {
    goToTestimonial((currentTestimonialIndex + 1) % totalTestimonials);
  }

  function prevTestimonial() {
    goToTestimonial(
      currentTestimonialIndex === 0
        ? totalTestimonials - 1
        : currentTestimonialIndex - 1,
    );
  }

  function updateTestimonialsSlider() {
    testimonialsTrack.style.transform = `translateX(-${
      currentTestimonialIndex * 100
    }%)`;

    document.querySelectorAll(".testimonial-dot").forEach((dot, index) => {
      dot.classList.toggle("active", index === currentTestimonialIndex);
    });
  }

  document
    .querySelector(".next-btn")
    .addEventListener("click", nextTestimonial);
  document
    .querySelector(".prev-btn")
    .addEventListener("click", prevTestimonial);

  // Auto-advance testimonials
  let testimonialInterval = setInterval(nextTestimonial, 5000);
  let isPaused = false;

  // Create pause/play button
  const testimonialsControls = document.querySelector(".testimonials-controls");
  const pausePlayBtn = document.createElement("button");
  pausePlayBtn.className = "testimonial-btn pause-play-btn";
  pausePlayBtn.innerHTML = '<i class="ri-pause-line"></i>';
  pausePlayBtn.setAttribute("aria-label", "Pause testimonials");

  // Insert pause button before the dots
  const dotsContainer = document.querySelector(".testimonials-dots");
  if (testimonialsControls && dotsContainer) {
    testimonialsControls.insertBefore(pausePlayBtn, dotsContainer);
  }

  // Pause/Play functionality
  pausePlayBtn.addEventListener("click", () => {
    if (isPaused) {
      // Resume
      testimonialInterval = setInterval(nextTestimonial, 5000);
      pausePlayBtn.innerHTML = '<i class="ri-pause-line"></i>';
      pausePlayBtn.setAttribute("aria-label", "Pause testimonials");
      isPaused = false;
    } else {
      // Pause
      clearInterval(testimonialInterval);
      pausePlayBtn.innerHTML = '<i class="ri-play-line"></i>';
      pausePlayBtn.setAttribute("aria-label", "Play testimonials");
      isPaused = true;
    }
  });

  // Render Awards
  const awardsContainer = document.querySelector(".awards-container");
  if (awardsContainer) {
    awards.forEach((award) => {
      const descriptionList = award.description
        .map((item) => `<li>${item}</li>`)
        .join("");

      let organizationIcon = "";
      if (award.organization === "Amazon") {
        organizationIcon = '<i class="fa-brands fa-amazon"></i>';
      } else if (
        award.organization.includes("Digital Egypt Pioneers Initiative")
      ) {
        organizationIcon =
          '<img src="assets/experience/DEPI.png" alt="DEPI" class="award-icon" />';
      }

      const awardCard = `
        <div class="award-card">
          <div class="award-header">
            <div class="award-title-section">
              <h3>${award.title}</h3>
              <p class="award-organization">${organizationIcon} ${award.organization}</p>
            </div>
            <p class="award-date">${award.date}</p>
          </div>
          <div class="award-content">
            <ul class="award-description">
              ${descriptionList}
            </ul>
            <a href="${award.certificate}" target="_blank" class="btn award-certificate-btn">
              <i class="fa-solid fa-certificate"></i> View Certificate
            </a>
          </div>
        </div>
      `;
      awardsContainer.innerHTML += awardCard;
    });
  }

  // AmanCity + Audoria: card slideshow autoplay on load (extra slides still lazy until shown)
  document.querySelectorAll(".project-slideshow").forEach((slideshow) => {
    startCardSlideshowAutoplay(slideshow);
  });
});

// Navbar active section highlight
const sections = document.querySelectorAll("section");
const navLinks = document.querySelectorAll(".navbar_link");

function activateNavLink() {
  let currentSection = sections[0];
  let scrollY = window.scrollY + 120;
  sections.forEach((section) => {
    if (
      section.offsetTop <= scrollY &&
      section.offsetTop + section.offsetHeight > scrollY
    ) {
      currentSection = section;
    }
  });
  navLinks.forEach((link) => {
    link.classList.remove("active");
    if (link.getAttribute("href") === `#${currentSection.id}`) {
      link.classList.add("active");
    }
  });
}

// Mobile Navbar Functionality
const navbarToggle = document.querySelector(".navbar_toggle");
const mobileMenu = document.querySelector(".mobile_menu");
const mobileLinks = document.querySelectorAll(".mobile_link");

function toggleMobileMenu() {
  navbarToggle.classList.toggle("active");
  mobileMenu.classList.toggle("active");

  // Prevent body scroll when menu is open
  if (mobileMenu.classList.contains("active")) {
    document.body.style.overflow = "hidden";
  } else {
    document.body.style.overflow = "";
  }
}

function closeMobileMenu() {
  navbarToggle.classList.remove("active");
  mobileMenu.classList.remove("active");
  document.body.style.overflow = "";
}

// Event listeners for mobile navbar
navbarToggle.addEventListener("click", toggleMobileMenu);

// Close mobile menu when clicking on a link
mobileLinks.forEach((link) => {
  link.addEventListener("click", closeMobileMenu);
});

// Close mobile menu when clicking outside
mobileMenu.addEventListener("click", (e) => {
  if (e.target === mobileMenu) {
    closeMobileMenu();
  }
});

// Close mobile menu on window resize (if screen becomes larger)
window.addEventListener("resize", () => {
  if (window.innerWidth > 768) {
    closeMobileMenu();
  }
});

window.addEventListener("scroll", activateNavLink);
window.addEventListener("DOMContentLoaded", activateNavLink);
